public abstract class ThresholdAlert implements AlertRule {
    private final int threshold;
    protected ThresholdAlert(int threshold) { this.threshold = threshold; }
    protected final int threshold() { return threshold; }
}

public final class HighAlert extends ThresholdAlert {
    public HighAlert(int threshold) { super(threshold); }
    @Override public boolean matches(int reading) { return reading > threshold(); }
}

public final class LowAlert extends ThresholdAlert {
    public LowAlert(int threshold) { super(threshold); }
    @Override public boolean matches(int reading) { return reading < threshold(); }
}

import java.util.List;
public final class RuleSet {
    private final List<AlertRule> rules;
    public RuleSet(List<AlertRule> rules) { this.rules = List.copyOf(rules); }
    public int matchingRules(int reading) {
        int count = 0;
        for (AlertRule rule : rules) if (rule.matches(reading)) count++;
        return count;
    }
}
